) AS (
  VALUES 
    (297::BIGINT, 'Es buena persona, aunque cuesta como profesor. Da explicaciones demasiado amplias que facilitan a que uno se disperse o se duerma. No da las evaluaciones a tiempo, tarda demasiado para hacer cualquier cosa. Parece que es un curso de 4 créds. Pero es pasable el curso si cumple con todo a tiempo.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'cbbcb1345881a2d5039dedd87c8cf46c09cfb867badb5c30c931762c7006b1ce'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Lo bueno de su clase es que puede pasar aunque en los dos proyectos no le haya ido tan bien, solo que tiene que hacer todos los kahoots, lecturas y ponerle a la investigación (con eso es un 50). El profe es buena nota calificando pero el asistente es un dolor. Llevaría con él otra vez.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2024-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'e21c82243b0d5478393fc5fe1069bb7395077f38ca75d066f924de83c2e55a41'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Basura de profe, no explica nada y deja proyectos complicados solo por que si, un asco de curso de los peores que he llevado'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2023-11-14T00:00:00+00:00'::TIMESTAMPTZ, '58a5d3530d910c2b787fe24a554fa29b2f8bea8b12dc623ece316cb22597edba'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'El curso se pasa solo, tiene que tener un buen equipo de trabajo y ser organizado entre las tareas, lecturas y proyectos. Los kahoots son sorpresa y son basados en las presentaciones de la clase, así que no puede faltar pero NUNCA explica nada ni enseña todo lo que pide en los proyectos.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '3f126799f7f128c63b92756496a50530de544c60a9774d1437707a7672859704'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Las clases no son las más entretenidas del mundo, pero si se presta atención puede aprender. Cada clase hay actividades de kahoot. Muchas tareas semanales (lecturas y tareas cortas). Los proyectos se pueden realizar de manera sencilla si tiene buen grupo de trabajo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2023-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'f9752e545d06992eb60541926fd12a543c495d9e236e4af44ed6c64c2603d00b'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'El mae no es malo, los proyectos son medio largos pero logrables, no se relacionan con la materia de clase. Busque un buen grupo, si tiene 3 compas para armarse un buen grupo el curso se hace facil. Piense muy bien con quien trabaja al puro inicio del curso.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2023-05-19T00:00:00+00:00'::TIMESTAMPTZ, '02925bd52d98895fd8bd8ace5e0b6f7356833bc1812963a7ddc515c8a79a8cc9'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Puedes pasar el curso sin ir a clases, porque no sirven de nada. Proyectos de sentarse todo el día porque son largos y complejos. Es bastante pasable por la distribución de la evaluación. Pasé el curso pero no aprendí nada. Matricula si solo quieres pasar y no quieres aprender.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '707e04141ac459d65b01d7c871ca0b73e224bcb9417bffaf328b6eb9bbf5145b'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'La materia que da no tiene nada que ver con los proyectos, deja demasiados trabajos para ser un curso de 3 créditos, a pesar todo eso, el curso es bastante pasable y es lo mejor que hay para bases a comparación de las otras opciones'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f4f94fa611fb7ccf727dbe046d82583c5a50e928b6e47c4cea61df649065d37a'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Los proyectos no tienen nada que ver con lo que enseña en clases. Deja demasiadas lecturas y tareas. No revisa hasta semana 17 y no le interesa el curso. Te responde los mensajes 2 semanas después de que le escribes. Deja mucho que desear como profesor'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2022-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'b33c417d80bae6079716f0a0c38ac389dc3603a00c53d725ca4fd56bee90051c'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Este profesor la verdad me decepciono. Son dos proyectos, uno que es bastante sencillo y para el otro se vuela demasiado. Nunca sube notas, nunca responde preguntas, las clases son inservibles. Lo unico importante de las clases son los quices de las lecturas y tareas semanales.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2022-06-02T00:00:00+00:00'::TIMESTAMPTZ, '6ddce7b35e34053387089b5ee7bf48ba369a1c6d39123afac54e77e2ac344838'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Los primeros temas son algo aburridos, porque puede ser similar a Bases I, pero después se pone mucho más interesante, traten de hacer todos los trabajos que les dejen lo más rápido posible porque se pueden acumular con los otros cursos'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'd12e66efb6f9734a8cbb3a78ef18b7ae5859626259c8aeeed01be09fb75cebd8'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Excelente profe, algunas clases fueron aburridas, pero se aprende un montón, los proyectos te obligan a investigar herramientas y cosas que son muy útiles, da puntos extra en tareas y proyectos, deja muchas lecturas, pero las deja desde el inicio del semestre así que uno las puede hacer con tiempo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'df46b1b5dd8f5aaf248ae8ddb4e2a1b315208eed5d4a91f1aa136aa1f3f1967b'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Muy buen profe, sus clases son aburridas, pero se aprende demasiado, los proyectos lo obligan a uno a investigar demasiadas herramientas por su cuenta y es muy entretenido, los proyectos lo hacen sentir útil a uno en la vida.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '3abc744fe9f21befb176acbb1e494a0e20ca94b6a2491279bf1983898f064561'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Sabe demasiado en este tema, no hace exámenes en realidad, el semestre se basa en puros proyectos/tareas/investigaciones. Totalmente recomendado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Inspirador']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, '69b1808aa10508905dba26f7abc8d7fc4090431b19c70eddaa7a7790e9c6e41a'::TEXT, ARRAY[1056]::BIGINT[]),
    (297::BIGINT, 'El profe explica muy bien. Las clases son entretenidas. Tantos los proyectos, como los examenes son rudos, pero uno aprende tanto que no importa. El profe esta dispuesto a cambiar fechas si uno lo necesita. Muy buen profesor.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b3193a34224dd4703ca66662c9a531da3cdb0c70dd764714ffabb36886ba3f28'::TEXT, ARRAY[1032]::BIGINT[]),
    (297::BIGINT, 'Sinceramente, fue mi profesor favorito durante el semestre, ni siquiera utilizaba mucho las diapositivas y daba un buen contraste de la materia con la situación laboral de la carrera como tal. Es un poco duro la verdad pero aprendí demasiado.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '633cff3ffeb05cc27db09d248d68f96862ef68f86de48058ebabbe693599037c'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Es un profesor interesante, sabe bien de la materia pero sus proyectos son bastante rudos.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2017-10-09T00:00:00+00:00'::TIMESTAMPTZ, 'fe366de1ef1e33fc549d1f7682368ad1cf94429f4f6ddddd3bb08d8419da15ec'::TEXT, ARRAY[1032]::BIGINT[]),
    (297::BIGINT, 'Muy tuanis. Es muy flexible con la entrega de los trabajos. Sabe mucho, las clases son muy interesantes, califica fuerte, pero es normal para este curso que ya es avanzado en la carrera.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'b18b19fb7acb524cad492fd737be9ee878943754906ba5affe616a8c6969a067'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Profe muy bueno, algunas clases son aburridas , pero enseña tas interesantes , lo que enseña es útil, sabe demasiado y es muy flexible con las fechas de entrega .'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'cc2c34c5fdf07e4a7d99317ae75aa66ed982c0388ce2b2407d23add8dd165610'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Sabe mucho sobre la materia y de computación en general. Las clases son un poco aburridas pero a la vez interesantes. Proyectos complicados pero realizables. Para los exámenes se debe estudiar bastante dado que son un poco difíciles y específicos.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-05T00:00:00+00:00'::TIMESTAMPTZ, '1348d574d9c4c70c0d0bcb4ab02dfc6ede30a74ae8c9b84bf8ba2142e63cce19'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Enseña bien, a veces sus clases pueden ser un poco aburridas pero la materia se va haciendo interesante porque él sabe mucho de lo que habla. Proyectos difíciles que realmente ponen a prueba las capacidades de uno pero nada realmente imposible, además él siempre está dispuesto a dar más tiempo.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-05T00:00:00+00:00'::TIMESTAMPTZ, 'aac248f2366bfcf9ec1f45b0f9fd5b13f2c741a6c74634b38e312c926f3db707'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Son clases pueden ser un poco aburridas, pero es el mejor profe para llevar Arqui.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-04T00:00:00+00:00'::TIMESTAMPTZ, '4fe9d54340702e70209c88a230e1bfdfde1c33381a667715c315dfc83c418929'::TEXT, ARRAY[1032]::BIGINT[]),
    (297::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'f0edf5982a913878436ae338b4ba25d8d68fc493902dd789d14c529914a3a0c0'::TEXT, ARRAY[1032]::BIGINT[]),
    (297::BIGINT, 'Buen profe, podría mejorar en hacer las clases un poco mas dinámicas, en algunas ocasiones se torna aburrido, recomendado .'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2016-07-06T00:00:00+00:00'::TIMESTAMPTZ, '49fa00059518386146ea60407ad85914635128ae80c27863ce47a540b5dfff0f'::TEXT, ARRAY[1032]::BIGINT[]),
    (297::BIGINT, 'Deja tareas normales, no hace tantos quices, bueno explicando la materia y progras MUY entretenidas. Aveces las clases se pueden tornar aburridas. El profe sabe demasiado, y siempre está dispuesto a ayudar. Progras duras pero se aprende muchísimo. Es flexible con las entregas. Recomendadísimo'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2016-05-23T00:00:00+00:00'::TIMESTAMPTZ, 'ccb99c7e056d868a2a2ed9ad76a06a94697a53c49f49e119d173a6bcb32d52e3'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Profe pura vida, buena persona. Tanto exámenes como quices 100% basados en lo que explica en clase. A veces se torna aburrido pero a veces deja las presentaciones y hace ejemplos en la pizarra. Progras de intermedio hacia arriba.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-03-19T00:00:00+00:00'::TIMESTAMPTZ, '83bc19d87cce916270bef9ae7ed39cfdc97a32780abf5f86b9cf0e4fd0876106'::TEXT, ARRAY[1032]::BIGINT[]),
    (297::BIGINT, 'Bueno, pero podria ser mejor. No es muy dificil, pero si hay mucho que hacer'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2016-02-24T00:00:00+00:00'::TIMESTAMPTZ, 'b84fce512e8f3e4fd3dc7bbca8912fd06d50152f4e39f5c1138ba42818a15cc4'::TEXT, ARRAY[1128]::BIGINT[]),
    (297::BIGINT, 'Las clases son de escucharlo hablar usando presentaciones. Solo cuando se llega al tema de ensamblador algunas son prácticas. Examenes medio difíciles pero pasables, igual con las progras. Dispuesto a ayudar. Es pura vida y amigable, aunque pueda parecer lo contrario.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-22T00:00:00+00:00'::TIMESTAMPTZ, '86dd603527c9d41bab498ef52809248595c7534dc1a65abec593c665b4104994'::TEXT, ARRAY[1032]::BIGINT[]),
    (297::BIGINT, 'Exámenes 100% basados en lo explicado en clase (Por eso tomar buenos apuntes o grabar las clases). Progras de dificultas fácil-media. El profesor explica muy bien todo y se preocupa que uno entienda el contenido. Flexible con proyectos y exámenes de dificultas media-fuerte y de selección´Única.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'a891408dd38f67ff69b9c32cd50756273a16768f2727b0a486e251eaffb3e000'::TEXT, ARRAY[1032]::BIGINT[]),
    (297::BIGINT, 'El profe usa diapositivas para dar clases, también da ejemplos que ayudan a entender mejor. Los examenes y quices son basados en lo que se ve en clase mas lo que esta en las diapositivas. Si se preocupa por que uno entienda. Las progras son pesadas pero nada del otro mundo. Recomendado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, '567b0e56459bbc4e3610e6372247ec572c837c15b758c638d03932e302f86ab1'::TEXT, ARRAY[1032]::BIGINT[]),
    (297::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-13T00:00:00+00:00'::TIMESTAMPTZ, '3e2f8d44395747fade2cfa82329f05da299af882b84329d35ba7eddd4eb0ee2d'::TEXT, ARRAY[1032]::BIGINT[]),
    (297::BIGINT, 'Se aprende poco, hay cosas q enseña q no son utiles, clases muy aburrudas da igual no ir, facil de pasar y si es buena nota'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, '6758b3899b17916587d814e2bcf6340fd6abb9b6e53d4212f504aebfe6684abd'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Un profesor muy pura vida, se interesa en que los estudiantes aprendan. Las clases son con diapositivas y pueden tornarse algo aburridas. Las progras son pesadas pero se aprende mucho! Los quices, tareas y examenes son pasables si se pone atención,todo esta en lo que dice y en las diapositivas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-03-09T00:00:00+00:00'::TIMESTAMPTZ, 'cece7c29db43f5afb8592592aebdcf4d7698a2298d2cd0a6c6ac22228d9546bd'::TEXT, ARRAY[1032]::BIGINT[]),
    (297::BIGINT, 'Excelente profesor; aunque sus clases de tornan algo aburridas. Explica bastante bien, ayuda al estudiante y deja progas rudas; y es fuerte calificando. Se aprende bastante :)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-29T00:00:00+00:00'::TIMESTAMPTZ, '29c6b1dbea04fb7130b787151ac761e88fef63e9bffbdc92ddc0696fc931b559'::TEXT, ARRAY[1032]::BIGINT[]),
    (297::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-07T00:00:00+00:00'::TIMESTAMPTZ, 'b648b42a761c36a02f2b73f33bc38bd13e9c82c02ca7789f6d73da22fb230416'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Excelente profesor y persona. Explica muy bien el contenido del curso, se preocupa por el estudiante. Da mucho ensamblador para arqui pero se aprende bastante que es lo importante. Juega de rudo pero no es para tanto como él dice.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'e418c0d07aa7234c184571d3914f049309df48ec16194f1e4f41ddcb59ea495a'::TEXT, ARRAY[1032]::BIGINT[]),
    (297::BIGINT, 'Proyectos duros, pero se aprende. Aunque debe mejorar la metodología de enseñanza para que la clase no se torne aburrida.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, '85425ace05dfb5f8d85ee292312c6cc745649ea7095055ea4b4770cf113e844d'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '1d9051abe8756f0fe4e92a9d859afcfe3efb065b6baff85899a2b71a1ed52b70'::TEXT, ARRAY[1032]::BIGINT[]),
    (297::BIGINT, 'Deja trabajos duros, de mucha investigación por parte del estudiante, sin embargo sabe mucho y se aprende bastante en el curso. Las clases pueden ser aburridas por ser iguales todas, pero se aprende, que es lo principal.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '2b2e61f90e1fce1faf2600758e548528e6ac5d0a9037a059be3d8ef8b24df6ea'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '6bb97eebe5abd61bc5cd7065d2409673856b2d5e8d2414ac611075dba94bf1c0'::TEXT, ARRAY[1043]::BIGINT[]),
    (297::BIGINT, 'El profe es rudo! Deja progras rudas y los examenes son matadores. Pero sabe muchísimo y la verdad explica muy bien. Es cuestión de ponerle, y mucho!'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '8559df85230b7cb011c412a0fb1ca17301b5dc5c23d8de3e472879b7c156eac3'::TEXT, ARRAY[1032]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
